WITH scored AS (SELECT id, starts_on, discount_pct, COUNT(discount_pct) OVER w_grp AS last7_count_discount_pct, MAX(discount_pct) OVER w_grp AS last7_max_discount_pct, MIN(discount_pct) OVER w_grp AS last7_min_discount_pct FROM promotions WHERE ends_on < '2025-06-01' WINDOW w_grp AS (PARTITION BY promo_code, channel ORDER BY ends_on, id ROWS BETWEEN 6 PRECEDING AND CURRENT ROW)) SELECT CASE WHEN last7_count_discount_pct >= 14 THEN 'HIGH' ELSE 'LOW' END AS last7_count_discount_pct_tier, COUNT(DISTINCT id) AS distinct_ids, COUNT(*) AS row_count, PERCENTILE_APPROX(last7_min_discount_pct, 0.95) AS last7_min_discount_pct_p95 FROM scored GROUP BY CASE WHEN last7_count_discount_pct >= 14 THEN 'HIGH' ELSE 'LOW' END HAVING COUNT(*) >= 1 ORDER BY row_count
